INSERT INTO sat_questions (question_id, external_id, vault_id, disclosed_item_id, source, program, test_type, test_type_desc, domain, primary_class_cd, skill_cd, skill_desc, difficulty, score_band_range_cd, question_type, stimulus_html, stem_html, answer_options, correct_answer, answer_keys, rationale_html, correct_answer_extracted_from_rationale, image_count, parent_template_name, parent_template_id, template_cluster_id, template_cluster_name, origin, position, answer_style, section, raw_payload, created_date, updated_date) VALUES
    ($SATQ$100269ad$SATQ$, $SATQ$b16da3dc-d20a-4b91-99b6-084363d6ac60$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Standard English Conventions$SATQ$, $SATQ$SEC$SATQ$, $SATQ$FSS$SATQ$, $SATQ$Form, Structure, and Sense$SATQ$, $SATQ$E$SATQ$, 2, $SATQ$mcq$SATQ$, $SATQ$<p>Zydeco music originated in the French Creole community of southwest Louisiana. One instrument that gives zydeco its unique sound is the vest frottoir. The vest frottoir <span aria-hidden="true">______</span><span class="sr-only">blank</span> a wearable washboard that is played by rubbing spoons or bottle openers against it.</p>$SATQ$, $SATQ$<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>$SATQ$, $SATQ$[{"id":"1a2ab45c-7993-4bdd-8b1f-8ec56ea70200","content":"<p>have been&nbsp;</p>"},{"id":"2e2ff336-bf1f-48ad-9cb9-b1a3a9ad9ce1","content":"<p>is</p>"},{"id":"fef756f6-03f5-40f7-9b9a-9cc3593d7674","content":"<p>were</p>"},{"id":"e4b90ea4-9dcc-41a9-aca8-3191398fddfc","content":"<p>are</p>"}]$SATQ$::jsonb, $SATQ$["B"]$SATQ$::jsonb, $SATQ$["2e2ff336-bf1f-48ad-9cb9-b1a3a9ad9ce1"]$SATQ$::jsonb, $SATQ$<p>Choice B is the best answer. The convention being tested is subject-verb agreement. The singular verb "is" agrees in number with the singular subject "vest frottoir."</p><p>Choice A is incorrect because the plural verb "have been" doesn&rsquo;t agree in number with the singular subject "vest frottoir." Choice C is incorrect because the plural verb "were" doesn&rsquo;t agree in number with the singular subject "vest frottoir." Choice D is incorrect because the plural verb "are" doesn&rsquo;t agree in number with the singular subject "vest frottoir."</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"100269ad","external_id":"b16da3dc-d20a-4b91-99b6-084363d6ac60","vaultid":null,"uId":"2579cebe-8278-469d-8da4-414f2a1a65fa","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"SEC","domain":"Standard English Conventions","skill_cd":"FSS","skill_desc":"Form, Structure, and Sense","difficulty":"E","score_band_range_cd":2,"type":"mcq","stimulus":"<p>Zydeco music originated in the French Creole community of southwest Louisiana. One instrument that gives zydeco its unique sound is the vest frottoir. The vest frottoir <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> a wearable washboard that is played by rubbing spoons or bottle openers against it.</p>","stem":"<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>","answerOptions":[{"id":"1a2ab45c-7993-4bdd-8b1f-8ec56ea70200","content":"<p>have been&nbsp;</p>"},{"id":"2e2ff336-bf1f-48ad-9cb9-b1a3a9ad9ce1","content":"<p>is</p>"},{"id":"fef756f6-03f5-40f7-9b9a-9cc3593d7674","content":"<p>were</p>"},{"id":"e4b90ea4-9dcc-41a9-aca8-3191398fddfc","content":"<p>are</p>"}],"keys":["2e2ff336-bf1f-48ad-9cb9-b1a3a9ad9ce1"],"correct_answer":["B"],"rationale":"<p>Choice B is the best answer. The convention being tested is subject-verb agreement. The singular verb \"is\" agrees in number with the singular subject \"vest frottoir.\"</p><p>Choice A is incorrect because the plural verb \"have been\" doesn&rsquo;t agree in number with the singular subject \"vest frottoir.\" Choice C is incorrect because the plural verb \"were\" doesn&rsquo;t agree in number with the singular subject \"vest frottoir.\" Choice D is incorrect because the plural verb \"are\" doesn&rsquo;t agree in number with the singular subject \"vest frottoir.\"</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1743430669212,"updateDate":1743430669212}$SATQ$::jsonb, 1743430669212, 1743430669212),
    ($SATQ$109d5bbb$SATQ$, $SATQ$24931307-5434-4663-9019-dffec331df9a$SATQ$::uuid, $SATQ$8fa913bf-2215-4b76-ba6b-4f5118afa854$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Standard English Conventions$SATQ$, $SATQ$SEC$SATQ$, $SATQ$BOU$SATQ$, $SATQ$Boundaries$SATQ$, $SATQ$H$SATQ$, 7, $SATQ$mcq$SATQ$, $SATQ$<p>With some 16,000 in attendance, the Second World Black and African Festival of Arts and <span aria-hidden="true">______</span><span class="sr-only">blank</span> or FESTAC &lsquo;77, as the event was more commonly known&mdash;became the largest pan-African event on record. FESTAC drew people from around the world to Lagos, Nigeria, for a monthlong celebration of Black and African art, scholarship, and activism.</p>$SATQ$, $SATQ$<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>$SATQ$, $SATQ$[{"id":"55819ece-9370-44a3-aca8-0468824d1b47","content":"<p>Culture:</p>"},{"id":"a1b82107-cf6c-48ec-8fdd-d0be0741e7bf","content":"<p>Culture&mdash;</p>"},{"id":"2ee5b895-df1d-4de3-9a0e-eeb275897693","content":"<p>Culture,</p>"},{"id":"d5214daa-d316-4f73-a51e-469b05cf0088","content":"<p>Culture</p>"}]$SATQ$::jsonb, $SATQ$["B"]$SATQ$::jsonb, $SATQ$["a1b82107-cf6c-48ec-8fdd-d0be0741e7bf"]$SATQ$::jsonb, $SATQ$<p>Choice B is the best answer. The text uses a dash to introduce a nonessential element that explains the acronym FESTAC. The dash matches the dash that comes after &ldquo;known,&rdquo; ending the descriptive aside. </p><p>Choice A is incorrect. A colon can only come after an independent clause, which isn&rsquo;t the case here. Choice C is incorrect. While punctuation is required to set off &ldquo;or FESTAC&hellip;known&rdquo; from the rest of the sentence, nonessential elements must be separated from the sentence with matching punctuation. Since a dash appears on the other side of the element, we can&rsquo;t use a comma here. Choice D is incorrect. The descriptive aside &ldquo;or FESTAC&hellip;known&rdquo; is a nonessential element that must be separated with punctuation from the rest of the sentence. This choice fails to add the necessary punctuation before the nonessential element. </p>$SATQ$, false, 0, $SATQ$OSP-KA-BOU-H006$SATQ$, $SATQ$$SATQ$, $SATQ$caf2735f-4fb6-48fe-b102-d6707e50d2a4$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"109d5bbb","external_id":"24931307-5434-4663-9019-dffec331df9a","vaultid":"8fa913bf-2215-4b76-ba6b-4f5118afa854","uId":"d73f40a5-f7d7-4ef5-bb74-af7e76d48c0b","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"SEC","domain":"Standard English Conventions","skill_cd":"BOU","skill_desc":"Boundaries","difficulty":"H","score_band_range_cd":7,"type":"mcq","stimulus":"<p>With some 16,000 in attendance, the Second World Black and African Festival of Arts and <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> or FESTAC &lsquo;77, as the event was more commonly known&mdash;became the largest pan-African event on record. FESTAC drew people from around the world to Lagos, Nigeria, for a monthlong celebration of Black and African art, scholarship, and activism.</p>","stem":"<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>","answerOptions":[{"id":"55819ece-9370-44a3-aca8-0468824d1b47","content":"<p>Culture:</p>"},{"id":"a1b82107-cf6c-48ec-8fdd-d0be0741e7bf","content":"<p>Culture&mdash;</p>"},{"id":"2ee5b895-df1d-4de3-9a0e-eeb275897693","content":"<p>Culture,</p>"},{"id":"d5214daa-d316-4f73-a51e-469b05cf0088","content":"<p>Culture</p>"}],"keys":["a1b82107-cf6c-48ec-8fdd-d0be0741e7bf"],"correct_answer":["B"],"rationale":"<p>Choice B is the best answer. The text uses a dash to introduce a nonessential element that explains the acronym FESTAC. The dash matches the dash that comes after &ldquo;known,&rdquo; ending the descriptive aside. </p><p>Choice A is incorrect. A colon can only come after an independent clause, which isn&rsquo;t the case here. Choice C is incorrect. While punctuation is required to set off &ldquo;or FESTAC&hellip;known&rdquo; from the rest of the sentence, nonessential elements must be separated from the sentence with matching punctuation. Since a dash appears on the other side of the element, we can&rsquo;t use a comma here. Choice D is incorrect. The descriptive aside &ldquo;or FESTAC&hellip;known&rdquo; is a nonessential element that must be separated with punctuation from the rest of the sentence. This choice fails to add the necessary punctuation before the nonessential element. </p>","parenttemplatename":"OSP-KA-BOU-H006","parenttemplateid":"","templateclusterid":"caf2735f-4fb6-48fe-b102-d6707e50d2a4","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959358,"updateDate":1691007959358}$SATQ$::jsonb, 1691007959358, 1691007959358),
    ($SATQ$12013e06$SATQ$, $SATQ$d0d16783-ef40-445f-a4e1-a033a0b35daa$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Standard English Conventions$SATQ$, $SATQ$SEC$SATQ$, $SATQ$BOU$SATQ$, $SATQ$Boundaries$SATQ$, $SATQ$M$SATQ$, 5, $SATQ$mcq$SATQ$, $SATQ$<p>In rural Minnesota, ecologist Leroy Walston conducted a study to determine whether seeding solar panel fields with wildflowers could bolster pollinator populations in nearby food crops. Walston&rsquo;s findings indicate that&mdash;assuming solar panel installers&rsquo; <span aria-hidden="true">______</span><span class="sr-only">blank</span> practice has the potential to increase the number of native bees in crops near solar fields throughout the Midwest by up to 20 percent.</p>$SATQ$, $SATQ$<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>$SATQ$, $SATQ$[{"id":"ce909646-9384-4fa7-8dc1-2a3af60d6077","content":"<p>cooperation<span data-ssml-say-as=\"characters\">,</span> this</p>"},{"id":"52d443e3-b113-415e-82f5-5fe4e2889b18","content":"<p>cooperation<span data-ssml-say-as=\"characters\">&mdash;</span>this</p>"},{"id":"979067b7-5dd8-4f03-80c4-f53d689d96c1","content":"<p>cooperation<span data-ssml-say-as=\"characters\">:</span> this</p>"},{"id":"f636e19c-2347-408b-b6ef-82f7b2e5303d","content":"<p>cooperation this</p>"}]$SATQ$::jsonb, $SATQ$["B"]$SATQ$::jsonb, $SATQ$["52d443e3-b113-415e-82f5-5fe4e2889b18"]$SATQ$::jsonb, $SATQ$<p>Choice B is the best answer. The convention being tested is the use of punctuation within a sentence. This choice correctly uses a dash after &ldquo;cooperation&rdquo; to pair with the dash after &ldquo;that&rdquo; to separate the supplementary element &ldquo;assuming solar panel installers&rsquo; cooperation&rdquo; from the rest of the sentence.</p><p>Choice A is incorrect because a comma can&rsquo;t be paired with a dash in this way to separate the supplementary element from the rest of the sentence. Choice C is incorrect because a colon can&rsquo;t be paired with a dash in this way to separate the supplementary element from the rest of the sentence. Choice D is incorrect because it fails to use appropriate punctuation to separate the supplemental element from the rest of the sentence.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"12013e06","external_id":"d0d16783-ef40-445f-a4e1-a033a0b35daa","vaultid":null,"uId":"c5162c4c-ade5-43c8-86bd-b5fe88dcd512","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"SEC","domain":"Standard English Conventions","skill_cd":"BOU","skill_desc":"Boundaries","difficulty":"M","score_band_range_cd":5,"type":"mcq","stimulus":"<p>In rural Minnesota, ecologist Leroy Walston conducted a study to determine whether seeding solar panel fields with wildflowers could bolster pollinator populations in nearby food crops. Walston&rsquo;s findings indicate that&mdash;assuming solar panel installers&rsquo; <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> practice has the potential to increase the number of native bees in crops near solar fields throughout the Midwest by up to 20 percent.</p>","stem":"<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>","answerOptions":[{"id":"ce909646-9384-4fa7-8dc1-2a3af60d6077","content":"<p>cooperation<span data-ssml-say-as=\"characters\">,</span> this</p>"},{"id":"52d443e3-b113-415e-82f5-5fe4e2889b18","content":"<p>cooperation<span data-ssml-say-as=\"characters\">&mdash;</span>this</p>"},{"id":"979067b7-5dd8-4f03-80c4-f53d689d96c1","content":"<p>cooperation<span data-ssml-say-as=\"characters\">:</span> this</p>"},{"id":"f636e19c-2347-408b-b6ef-82f7b2e5303d","content":"<p>cooperation this</p>"}],"keys":["52d443e3-b113-415e-82f5-5fe4e2889b18"],"correct_answer":["B"],"rationale":"<p>Choice B is the best answer. The convention being tested is the use of punctuation within a sentence. This choice correctly uses a dash after &ldquo;cooperation&rdquo; to pair with the dash after &ldquo;that&rdquo; to separate the supplementary element &ldquo;assuming solar panel installers&rsquo; cooperation&rdquo; from the rest of the sentence.</p><p>Choice A is incorrect because a comma can&rsquo;t be paired with a dash in this way to separate the supplementary element from the rest of the sentence. Choice C is incorrect because a colon can&rsquo;t be paired with a dash in this way to separate the supplementary element from the rest of the sentence. Choice D is incorrect because it fails to use appropriate punctuation to separate the supplemental element from the rest of the sentence.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1776362771170,"updateDate":1776362771170}$SATQ$::jsonb, 1776362771170, 1776362771170),
    ($SATQ$12bd5b75$SATQ$, $SATQ$5f1c6db1-57fc-46f3-9c97-1b9bb3e6c25e$SATQ$::uuid, $SATQ$b5906944-e2e5-4ca4-af12-d5a89d00fa71$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Standard English Conventions$SATQ$, $SATQ$SEC$SATQ$, $SATQ$FSS$SATQ$, $SATQ$Form, Structure, and Sense$SATQ$, $SATQ$E$SATQ$, 1, $SATQ$mcq$SATQ$, $SATQ$<p>With its towering, six-spired exterior of granitelike quartz monzonite, the Salt Lake Temple is one of the most instantly recognizable structures in the state of Utah. However, many people do not know that <span aria-hidden="true">______</span><span class="sr-only">blank</span> built over the course of forty years, with construction beginning in 1853 and ending in 1893.</p>$SATQ$, $SATQ$<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>$SATQ$, $SATQ$[{"id":"91fb6e51-55fe-4b10-a630-64d07a17adac","content":"<p>it was</p>"},{"id":"c5c3c573-0af4-4aeb-bcf9-56696b5913b0","content":"<p>one was</p>"},{"id":"d9c2b1b4-bcc9-422b-a011-c9165edfa87c","content":"<p>they were</p>"},{"id":"5fc17a6b-1a05-412a-a65c-05c03d83caf6","content":"<p>both were</p>"}]$SATQ$::jsonb, $SATQ$["A"]$SATQ$::jsonb, $SATQ$["91fb6e51-55fe-4b10-a630-64d07a17adac"]$SATQ$::jsonb, $SATQ$<p>Choice A is the best answer. The convention being tested is pronoun-antecedent agreement. The singular pronoun "it" agrees in number with the singular antecedent "the Salt Lake Temple."</p><p>Choice B is incorrect because the singular pronoun "one" is ambiguous in this context; the resulting sentence leaves unclear whether there is only one Salt Lake temple or multiple. Choice C is incorrect because the plural pronoun "they" doesn&rsquo;t agree in number with the singular antecedent "the Salt Lake Temple." Choice D is incorrect because the plural pronoun "both" doesn&rsquo;t agree in number with the singular antecedent "the Salt Lake Temple."</p>$SATQ$, false, 0, $SATQ$OSP-749-SEC$SATQ$, $SATQ$$SATQ$, $SATQ$d365dd7f-7378-4925-924e-061eae554c01$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"12bd5b75","external_id":"5f1c6db1-57fc-46f3-9c97-1b9bb3e6c25e","vaultid":"b5906944-e2e5-4ca4-af12-d5a89d00fa71","uId":"f92b52a4-61ea-4aa0-80a4-f10bc6179b29","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"SEC","domain":"Standard English Conventions","skill_cd":"FSS","skill_desc":"Form, Structure, and Sense","difficulty":"E","score_band_range_cd":1,"type":"mcq","stimulus":"<p>With its towering, six-spired exterior of granitelike quartz monzonite, the Salt Lake Temple is one of the most instantly recognizable structures in the state of Utah. However, many people do not know that <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> built over the course of forty years, with construction beginning in 1853 and ending in 1893.</p>","stem":"<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>","answerOptions":[{"id":"91fb6e51-55fe-4b10-a630-64d07a17adac","content":"<p>it was</p>"},{"id":"c5c3c573-0af4-4aeb-bcf9-56696b5913b0","content":"<p>one was</p>"},{"id":"d9c2b1b4-bcc9-422b-a011-c9165edfa87c","content":"<p>they were</p>"},{"id":"5fc17a6b-1a05-412a-a65c-05c03d83caf6","content":"<p>both were</p>"}],"keys":["91fb6e51-55fe-4b10-a630-64d07a17adac"],"correct_answer":["A"],"rationale":"<p>Choice A is the best answer. The convention being tested is pronoun-antecedent agreement. The singular pronoun \"it\" agrees in number with the singular antecedent \"the Salt Lake Temple.\"</p><p>Choice B is incorrect because the singular pronoun \"one\" is ambiguous in this context; the resulting sentence leaves unclear whether there is only one Salt Lake temple or multiple. Choice C is incorrect because the plural pronoun \"they\" doesn&rsquo;t agree in number with the singular antecedent \"the Salt Lake Temple.\" Choice D is incorrect because the plural pronoun \"both\" doesn&rsquo;t agree in number with the singular antecedent \"the Salt Lake Temple.\"</p>","parenttemplatename":"OSP-749-SEC","parenttemplateid":"","templateclusterid":"d365dd7f-7378-4925-924e-061eae554c01","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959350,"updateDate":1691007959350}$SATQ$::jsonb, 1691007959350, 1691007959350),
    ($SATQ$13fcf575$SATQ$, $SATQ$a5e68a12-2354-4595-9f2a-47885f367e02$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Standard English Conventions$SATQ$, $SATQ$SEC$SATQ$, $SATQ$BOU$SATQ$, $SATQ$Boundaries$SATQ$, $SATQ$H$SATQ$, 7, $SATQ$mcq$SATQ$, $SATQ$<p>Roughly 300 nights a year, when the cold air descending from the Andes Mountains meets the warm air rising from Venezuela&rsquo;s coastal Lake Maracaibo, the result is a spectacular lightning storm, its strikes so bright, so localized, and so <span aria-hidden="true">______</span><span class="sr-only">blank</span> that it has become known as &ldquo;Maracaibo&rsquo;s Lighthouse.&rdquo;</p>$SATQ$, $SATQ$<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>$SATQ$, $SATQ$[{"id":"3e0e3ce1-3ad4-48ef-b5dd-a395dc5a35ff","content":"<p>dependable:&nbsp;</p>"},{"id":"45d51593-3fc7-461b-ad63-3f17f2cf629d","content":"<p>dependable;&nbsp;</p>"},{"id":"b97cab64-c03b-4d68-8173-eaf572ec7f8e","content":"<p>dependable&nbsp;</p>"},{"id":"05bb8643-e6be-468a-9a2f-37fec1baa3df","content":"<p>dependable,&nbsp;</p>"}]$SATQ$::jsonb, $SATQ$["C"]$SATQ$::jsonb, $SATQ$["b97cab64-c03b-4d68-8173-eaf572ec7f8e"]$SATQ$::jsonb, $SATQ$<p>Choice C is the best answer. The convention being tested is the punctuation of an integrated relative clause. No punctuation is needed before the relative clause beginning with "that" because the content of the relative clause ("that...Lighthouse") is integral to the meaning of the coordinated adjectival phrase ("so bright, so localized, and so dependable") that it modifies.</p><p>Choice A is incorrect because no punctuation is needed between the coordinated adjectival phrase ("so bright...dependable") and the integrated relative clause that modifies it. Choice B is incorrect because no punctuation is needed between the coordinated adjectival phrase ("so bright...dependable") and the integrated relative clause that modifies it. Choice D is incorrect because no punctuation is needed between the coordinated adjectival phrase ("so bright...dependable") and the integrated relative clause that modifies it.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"13fcf575","external_id":"a5e68a12-2354-4595-9f2a-47885f367e02","vaultid":null,"uId":"0f004f16-c431-4303-84b7-b4340f0d6481","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"SEC","domain":"Standard English Conventions","skill_cd":"BOU","skill_desc":"Boundaries","difficulty":"H","score_band_range_cd":7,"type":"mcq","stimulus":"<p>Roughly 300 nights a year, when the cold air descending from the Andes Mountains meets the warm air rising from Venezuela&rsquo;s coastal Lake Maracaibo, the result is a spectacular lightning storm, its strikes so bright, so localized, and so <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> that it has become known as &ldquo;Maracaibo&rsquo;s Lighthouse.&rdquo;</p>","stem":"<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>","answerOptions":[{"id":"3e0e3ce1-3ad4-48ef-b5dd-a395dc5a35ff","content":"<p>dependable:&nbsp;</p>"},{"id":"45d51593-3fc7-461b-ad63-3f17f2cf629d","content":"<p>dependable;&nbsp;</p>"},{"id":"b97cab64-c03b-4d68-8173-eaf572ec7f8e","content":"<p>dependable&nbsp;</p>"},{"id":"05bb8643-e6be-468a-9a2f-37fec1baa3df","content":"<p>dependable,&nbsp;</p>"}],"keys":["b97cab64-c03b-4d68-8173-eaf572ec7f8e"],"correct_answer":["C"],"rationale":"<p>Choice C is the best answer. The convention being tested is the punctuation of an integrated relative clause. No punctuation is needed before the relative clause beginning with \"that\" because the content of the relative clause (\"that...Lighthouse\") is integral to the meaning of the coordinated adjectival phrase (\"so bright, so localized, and so dependable\") that it modifies.</p><p>Choice A is incorrect because no punctuation is needed between the coordinated adjectival phrase (\"so bright...dependable\") and the integrated relative clause that modifies it. Choice B is incorrect because no punctuation is needed between the coordinated adjectival phrase (\"so bright...dependable\") and the integrated relative clause that modifies it. Choice D is incorrect because no punctuation is needed between the coordinated adjectival phrase (\"so bright...dependable\") and the integrated relative clause that modifies it.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1730147323048,"updateDate":1730147323048}$SATQ$::jsonb, 1730147323048, 1730147323048),
    ($SATQ$1448f43f$SATQ$, $SATQ$ba9730c7-12fd-40aa-b7ac-b72bb15ef79e$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Standard English Conventions$SATQ$, $SATQ$SEC$SATQ$, $SATQ$FSS$SATQ$, $SATQ$Form, Structure, and Sense$SATQ$, $SATQ$E$SATQ$, 2, $SATQ$mcq$SATQ$, $SATQ$<p>Unsupervised machine learning is an approach that computer scientists like Nina Miolane use to engineer artificial intelligence technologies. It involves training computer algorithms to organize unlabeled data sets. Multitask learning is another approach. <span aria-hidden="true">______</span><span class="sr-only">blank</span> involves training computer models to perform multiple tasks at the same time.</p>$SATQ$, $SATQ$<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>$SATQ$, $SATQ$[{"id":"96e5a12e-71a9-4186-a870-65b6fbd9cfb5","content":"<p>Those</p>"},{"id":"ef615d54-2571-48af-9df0-1261bd9327c4","content":"<p>They</p>"},{"id":"f8846a28-ef27-41e8-b40c-b35dfcda874a","content":"<p>It</p>"},{"id":"1642b9f2-2c08-4a0e-a252-d0e2e57aaf17","content":"<p>Some</p>"}]$SATQ$::jsonb, $SATQ$["C"]$SATQ$::jsonb, $SATQ$["f8846a28-ef27-41e8-b40c-b35dfcda874a"]$SATQ$::jsonb, $SATQ$<p>Choice C is the best answer. The convention being tested is pronoun-antecedent agreement. The singular pronoun "it" agrees in number with the singular antecedent "multitask learning" and clearly indicates what multitask learning involves.</p><p>Choice A is incorrect because the plural demonstrative pronoun "those" doesn&rsquo;t agree in number with the singular antecedent "multitask learning." Choice B is incorrect because the plural pronoun "they" doesn&rsquo;t agree in number with the singular antecedent "multitask learning." Choice D is incorrect because the indefinite pronoun "some" is ambiguous in this context; the resulting sentence leaves unclear what exactly "involves training computer models."</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"1448f43f","external_id":"ba9730c7-12fd-40aa-b7ac-b72bb15ef79e","vaultid":null,"uId":"a915d52d-776c-481f-82ed-1f32a6d0552c","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"SEC","domain":"Standard English Conventions","skill_cd":"FSS","skill_desc":"Form, Structure, and Sense","difficulty":"E","score_band_range_cd":2,"type":"mcq","stimulus":"<p>Unsupervised machine learning is an approach that computer scientists like Nina Miolane use to engineer artificial intelligence technologies. It involves training computer algorithms to organize unlabeled data sets. Multitask learning is another approach. <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> involves training computer models to perform multiple tasks at the same time.</p>","stem":"<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>","answerOptions":[{"id":"96e5a12e-71a9-4186-a870-65b6fbd9cfb5","content":"<p>Those</p>"},{"id":"ef615d54-2571-48af-9df0-1261bd9327c4","content":"<p>They</p>"},{"id":"f8846a28-ef27-41e8-b40c-b35dfcda874a","content":"<p>It</p>"},{"id":"1642b9f2-2c08-4a0e-a252-d0e2e57aaf17","content":"<p>Some</p>"}],"keys":["f8846a28-ef27-41e8-b40c-b35dfcda874a"],"correct_answer":["C"],"rationale":"<p>Choice C is the best answer. The convention being tested is pronoun-antecedent agreement. The singular pronoun \"it\" agrees in number with the singular antecedent \"multitask learning\" and clearly indicates what multitask learning involves.</p><p>Choice A is incorrect because the plural demonstrative pronoun \"those\" doesn&rsquo;t agree in number with the singular antecedent \"multitask learning.\" Choice B is incorrect because the plural pronoun \"they\" doesn&rsquo;t agree in number with the singular antecedent \"multitask learning.\" Choice D is incorrect because the indefinite pronoun \"some\" is ambiguous in this context; the resulting sentence leaves unclear what exactly \"involves training computer models.\"</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1755117061191,"updateDate":1755117061191}$SATQ$::jsonb, 1755117061191, 1755117061191),
    ($SATQ$145d5ca7$SATQ$, $SATQ$cd06b390-9a40-4a9a-9f19-eaf6c6d27ea1$SATQ$::uuid, $SATQ$43258d1b-2f2e-4023-a0a5-2d567d62f80c$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Standard English Conventions$SATQ$, $SATQ$SEC$SATQ$, $SATQ$BOU$SATQ$, $SATQ$Boundaries$SATQ$, $SATQ$M$SATQ$, 5, $SATQ$mcq$SATQ$, $SATQ$<p>Gathering accurate data on water flow in the United States is challenging because of the country&rsquo;s millions of miles of <span aria-hidden="true">______</span><span class="sr-only">blank</span> the volume and speed of water at any given location can vary drastically over time.</p>$SATQ$, $SATQ$<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>$SATQ$, $SATQ$[{"id":"0be1a12c-0d1e-4dda-ae49-dd9b2ac3ce8d","content":"<p>waterways and the fact that,</p>"},{"id":"c6ba976d-c860-43b7-b554-20d6643f4be5","content":"<p>waterways, and the fact that,</p>"},{"id":"9cf02411-bb24-404c-b23c-6c7b40993507","content":"<p>waterways, and, the fact that</p>"},{"id":"5d7e8188-3db2-495f-b04a-9d1425b2c021","content":"<p>waterways and the fact that</p>"}]$SATQ$::jsonb, $SATQ$["D"]$SATQ$::jsonb, $SATQ$["5d7e8188-3db2-495f-b04a-9d1425b2c021"]$SATQ$::jsonb, $SATQ$<p>Choice D is the best answer. The convention being tested is punctuation within two coordinated noun phrases. When, as in this case, a noun phrase (&ldquo;the country&rsquo;s millions of miles of waterways&rdquo;) is coordinated with another noun phrase (&ldquo;the fact&rdquo;) followed by an integrated relative clause (&ldquo;that the volume...time&rdquo;), no punctuation is needed. </p><p>Choice A is incorrect because no punctuation is needed. Choice B is incorrect because no punctuation is needed. Choice C is incorrect because no punctuation is needed. </p>$SATQ$, false, 0, $SATQ$OSP-640-SEC$SATQ$, $SATQ$$SATQ$, $SATQ$774cf5ec-1e9b-44f6-836b-bfbac4ce95e7$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"145d5ca7","external_id":"cd06b390-9a40-4a9a-9f19-eaf6c6d27ea1","vaultid":"43258d1b-2f2e-4023-a0a5-2d567d62f80c","uId":"4b324750-6e35-4cad-928a-502d3099fddd","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"SEC","domain":"Standard English Conventions","skill_cd":"BOU","skill_desc":"Boundaries","difficulty":"M","score_band_range_cd":5,"type":"mcq","stimulus":"<p>Gathering accurate data on water flow in the United States is challenging because of the country&rsquo;s millions of miles of <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> the volume and speed of water at any given location can vary drastically over time.</p>","stem":"<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>","answerOptions":[{"id":"0be1a12c-0d1e-4dda-ae49-dd9b2ac3ce8d","content":"<p>waterways and the fact that,</p>"},{"id":"c6ba976d-c860-43b7-b554-20d6643f4be5","content":"<p>waterways, and the fact that,</p>"},{"id":"9cf02411-bb24-404c-b23c-6c7b40993507","content":"<p>waterways, and, the fact that</p>"},{"id":"5d7e8188-3db2-495f-b04a-9d1425b2c021","content":"<p>waterways and the fact that</p>"}],"keys":["5d7e8188-3db2-495f-b04a-9d1425b2c021"],"correct_answer":["D"],"rationale":"<p>Choice D is the best answer. The convention being tested is punctuation within two coordinated noun phrases. When, as in this case, a noun phrase (&ldquo;the country&rsquo;s millions of miles of waterways&rdquo;) is coordinated with another noun phrase (&ldquo;the fact&rdquo;) followed by an integrated relative clause (&ldquo;that the volume...time&rdquo;), no punctuation is needed. </p><p>Choice A is incorrect because no punctuation is needed. Choice B is incorrect because no punctuation is needed. Choice C is incorrect because no punctuation is needed. </p>","parenttemplatename":"OSP-640-SEC","parenttemplateid":"","templateclusterid":"774cf5ec-1e9b-44f6-836b-bfbac4ce95e7","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959340,"updateDate":1691007959340}$SATQ$::jsonb, 1691007959340, 1691007959340),
    ($SATQ$148be4da$SATQ$, $SATQ$607efa95-e3e3-4977-8e7b-f0388cebb5b5$SATQ$::uuid, $SATQ$7aacc1ca-9c43-40af-abc1-be1cfdb06298$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Standard English Conventions$SATQ$, $SATQ$SEC$SATQ$, $SATQ$BOU$SATQ$, $SATQ$Boundaries$SATQ$, $SATQ$E$SATQ$, 2, $SATQ$mcq$SATQ$, $SATQ$<p>Human-made (synthetic) fibers used in clothes and many other consumer products are more durable than most natural plant <span aria-hidden="true">______</span><span class="sr-only">blank</span> the manufacture of synthetic fibers requires toxic chemical solvents that can pollute air and water.</p>$SATQ$, $SATQ$<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>$SATQ$, $SATQ$[{"id":"7b016f3d-1710-41f6-b3ac-41d87f1d4403","content":"<p>fibers,</p>"},{"id":"2e8163cc-7b94-4d59-a342-90c55c40d24e","content":"<p>fibers but</p>"},{"id":"01660b8f-964d-400b-abcc-825e4428393d","content":"<p>fibers</p>"},{"id":"f57fd940-58b9-44ee-8dda-cbec03a42208","content":"<p>fibers, but</p>"}]$SATQ$::jsonb, $SATQ$["D"]$SATQ$::jsonb, $SATQ$["f57fd940-58b9-44ee-8dda-cbec03a42208"]$SATQ$::jsonb, $SATQ$<p>Choice D is the best answer. The convention being tested is the coordination of main clauses within a sentence. This choice correctly uses a comma and the coordinating conjunction &ldquo;but&rdquo; to join the first main clause (&ldquo;Human-made...fibers&rdquo;) and the second main clause (&ldquo;the manufacture...water&rdquo;). </p><p>Choice A is incorrect because it results in a comma splice. Without a conjunction following it, a comma can&rsquo;t be used in this way to join two main clauses. Choice B is incorrect because when coordinating two longer main clauses such as these, it&rsquo;s conventional to use a comma before the coordinating conjunction. Choice C is incorrect because it results in a run-on sentence. The two main clauses are fused without punctuation and/or a conjunction.&nbsp;</p>$SATQ$, false, 0, $SATQ$OSP-712-SEC$SATQ$, $SATQ$$SATQ$, $SATQ$9d49f659-41b8-45cb-86df-e0cd8b8fd188$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"148be4da","external_id":"607efa95-e3e3-4977-8e7b-f0388cebb5b5","vaultid":"7aacc1ca-9c43-40af-abc1-be1cfdb06298","uId":"1395fb9d-9a97-4070-a3f4-aa6dab97dc58","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"SEC","domain":"Standard English Conventions","skill_cd":"BOU","skill_desc":"Boundaries","difficulty":"E","score_band_range_cd":2,"type":"mcq","stimulus":"<p>Human-made (synthetic) fibers used in clothes and many other consumer products are more durable than most natural plant <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> the manufacture of synthetic fibers requires toxic chemical solvents that can pollute air and water.</p>","stem":"<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>","answerOptions":[{"id":"7b016f3d-1710-41f6-b3ac-41d87f1d4403","content":"<p>fibers,</p>"},{"id":"2e8163cc-7b94-4d59-a342-90c55c40d24e","content":"<p>fibers but</p>"},{"id":"01660b8f-964d-400b-abcc-825e4428393d","content":"<p>fibers</p>"},{"id":"f57fd940-58b9-44ee-8dda-cbec03a42208","content":"<p>fibers, but</p>"}],"keys":["f57fd940-58b9-44ee-8dda-cbec03a42208"],"correct_answer":["D"],"rationale":"<p>Choice D is the best answer. The convention being tested is the coordination of main clauses within a sentence. This choice correctly uses a comma and the coordinating conjunction &ldquo;but&rdquo; to join the first main clause (&ldquo;Human-made...fibers&rdquo;) and the second main clause (&ldquo;the manufacture...water&rdquo;). </p><p>Choice A is incorrect because it results in a comma splice. Without a conjunction following it, a comma can&rsquo;t be used in this way to join two main clauses. Choice B is incorrect because when coordinating two longer main clauses such as these, it&rsquo;s conventional to use a comma before the coordinating conjunction. Choice C is incorrect because it results in a run-on sentence. The two main clauses are fused without punctuation and/or a conjunction.&nbsp;</p>","parenttemplatename":"OSP-712-SEC","parenttemplateid":"","templateclusterid":"9d49f659-41b8-45cb-86df-e0cd8b8fd188","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959348,"updateDate":1691007959348}$SATQ$::jsonb, 1691007959348, 1691007959348),
    ($SATQ$155239cf$SATQ$, $SATQ$155379f1-163d-4cfe-89ff-ea5219cd2f3a$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Standard English Conventions$SATQ$, $SATQ$SEC$SATQ$, $SATQ$BOU$SATQ$, $SATQ$Boundaries$SATQ$, $SATQ$E$SATQ$, 1, $SATQ$mcq$SATQ$, $SATQ$<p>By analyzing ice cores from Greenland and Antarctica, a research team at Sweden&rsquo;s Lund University discovered evidence of a solar storm that occurred 9,200 years ago. Scientists had previously thought the Sun to be in a relatively &ldquo;quiet&rdquo; phase at that <span aria-hidden="true">______</span><span class="sr-only">blank</span> the Lund team&rsquo;s finding suggests otherwise.</p>$SATQ$, $SATQ$<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>$SATQ$, $SATQ$[{"id":"a5a1e5fc-6290-4136-b174-ebc81397d32d","content":"<p>time but</p>"},{"id":"345f492e-da1c-4065-9d76-2bef038aae6d","content":"<p>time, but</p>"},{"id":"57b23aa6-7716-4ed9-975b-d70777ef008d","content":"<p>time,</p>"},{"id":"015daf56-e413-4da6-9f56-b0822fed1979","content":"<p>time</p>"}]$SATQ$::jsonb, $SATQ$["B"]$SATQ$::jsonb, $SATQ$["345f492e-da1c-4065-9d76-2bef038aae6d"]$SATQ$::jsonb, $SATQ$<p>Choice B is the best answer. The convention being tested is the coordination of main clauses within a sentence. This choice correctly uses a comma and the coordinating conjunction "but" to join the first main clause ("Scientists...time") and the second main clause ("the Lund...otherwise").</p><p>Choice A is incorrect because when coordinating two longer main clauses such as these, it&rsquo;s conventional to use a comma before the coordinating conjunction. Choice C is incorrect because it results in a comma splice. Without a conjunction following it, a comma can&rsquo;t be used in this way to join two main clauses. Choice D is incorrect because it results in a run-on sentence. The two main clauses are fused without punctuation and/or a conjunction.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"155239cf","external_id":"155379f1-163d-4cfe-89ff-ea5219cd2f3a","vaultid":null,"uId":"26e0c01a-81a4-4812-ba24-12bc535b2bee","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"SEC","domain":"Standard English Conventions","skill_cd":"BOU","skill_desc":"Boundaries","difficulty":"E","score_band_range_cd":1,"type":"mcq","stimulus":"<p>By analyzing ice cores from Greenland and Antarctica, a research team at Sweden&rsquo;s Lund University discovered evidence of a solar storm that occurred 9,200 years ago. Scientists had previously thought the Sun to be in a relatively &ldquo;quiet&rdquo; phase at that <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> the Lund team&rsquo;s finding suggests otherwise.</p>","stem":"<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>","answerOptions":[{"id":"a5a1e5fc-6290-4136-b174-ebc81397d32d","content":"<p>time but</p>"},{"id":"345f492e-da1c-4065-9d76-2bef038aae6d","content":"<p>time, but</p>"},{"id":"57b23aa6-7716-4ed9-975b-d70777ef008d","content":"<p>time,</p>"},{"id":"015daf56-e413-4da6-9f56-b0822fed1979","content":"<p>time</p>"}],"keys":["345f492e-da1c-4065-9d76-2bef038aae6d"],"correct_answer":["B"],"rationale":"<p>Choice B is the best answer. The convention being tested is the coordination of main clauses within a sentence. This choice correctly uses a comma and the coordinating conjunction \"but\" to join the first main clause (\"Scientists...time\") and the second main clause (\"the Lund...otherwise\").</p><p>Choice A is incorrect because when coordinating two longer main clauses such as these, it&rsquo;s conventional to use a comma before the coordinating conjunction. Choice C is incorrect because it results in a comma splice. Without a conjunction following it, a comma can&rsquo;t be used in this way to join two main clauses. Choice D is incorrect because it results in a run-on sentence. The two main clauses are fused without punctuation and/or a conjunction.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1730147323047,"updateDate":1730147323047}$SATQ$::jsonb, 1730147323047, 1730147323047),
    ($SATQ$15d6d837$SATQ$, $SATQ$f527771a-3e59-4565-ac50-fc13a5b072dd$SATQ$::uuid, $SATQ$8441663c-0d94-4d11-9834-f03c92bb360f$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Standard English Conventions$SATQ$, $SATQ$SEC$SATQ$, $SATQ$FSS$SATQ$, $SATQ$Form, Structure, and Sense$SATQ$, $SATQ$E$SATQ$, 3, $SATQ$mcq$SATQ$, $SATQ$<p>Literary agents estimate that more than half of all nonfiction books credited to a celebrity or other public figure are in fact written by ghostwriters, professional authors who are paid to write other <span aria-hidden="true">______</span><span class="sr-only">blank</span> but whose names never appear on book covers.</p>$SATQ$, $SATQ$<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>$SATQ$, $SATQ$[{"id":"58d0a35d-9c03-4e0c-b877-55e03bea9845","content":"<p>people&rsquo;s stories</p>"},{"id":"baddc949-252e-454f-925a-d2c76a3ca08f","content":"<p>peoples story&rsquo;s</p>"},{"id":"81562a4e-acd5-43cd-b098-9f0dcc06a1ab","content":"<p>peoples stories</p>"},{"id":"016cf8ce-4d7b-4500-b8c0-384836e83019","content":"<p>people&rsquo;s story&rsquo;s</p>"}]$SATQ$::jsonb, $SATQ$["A"]$SATQ$::jsonb, $SATQ$["58d0a35d-9c03-4e0c-b877-55e03bea9845"]$SATQ$::jsonb, $SATQ$<p>Choice A is the best answer. The convention being tested is the use of plural and possessive nouns. The plural possessive noun &ldquo;people&rsquo;s&rdquo; and the plural noun &ldquo;stories&rdquo; correctly indicate that there are multiple stories from multiple people.&nbsp;</p><p>Choice B is incorrect because the context requires the plural possessive noun &ldquo;people&rsquo;s&rdquo; and the plural noun &ldquo;stories,&rdquo; not the plural noun &ldquo;peoples&rdquo; and the singular possessive noun &ldquo;story&rsquo;s.&rdquo; Choice C is incorrect because the context requires the plural possessive noun &ldquo;people&rsquo;s,&rdquo; not the plural noun &ldquo;peoples.&rdquo; Choice D is incorrect be